import{_ as e,o as t,c as r,a3 as o}from"./chunks/framework.D3kUw6rp.js";const i="/assets/bike.7l5UIE9I.jpeg",s="/assets/%E5%8F%98%E9%80%9F%E5%99%A8.C9wl1UPF.webp",l="/assets/%E5%86%85%E8%83%8E.BDZsIqh9.jpeg",c="/assets/%E8%A1%A5%E8%83%8E.CnfdAd5X.jpeg",n="/assets/%E8%A3%85%E5%86%85%E8%83%8E.CuW8aWek.jpeg",q=JSON.parse('{"title":"骑行知识","description":"","frontmatter":{},"headers":[],"relativePath":"article/2024/bicycle/index.md","filePath":"article/2024/bicycle/index.md"}'),p={name:"article/2024/bicycle/index.md"};function d(h,a,_,m,u,b){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="骑行知识" tabindex="-1">骑行知识 <a class="header-anchor" href="#骑行知识" aria-label="Permalink to &quot;骑行知识&quot;">​</a></h1><h2 id="捷安特-atx-660" tabindex="-1">捷安特 ATX 660 <a class="header-anchor" href="#捷安特-atx-660" aria-label="Permalink to &quot;捷安特 ATX 660&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><h2 id="正确使用变速器" tabindex="-1">正确使用变速器 <a class="header-anchor" href="#正确使用变速器" aria-label="Permalink to &quot;正确使用变速器&quot;">​</a></h2><h3 id="_1、踏频" tabindex="-1">1、踏频 <a class="header-anchor" href="#_1、踏频" aria-label="Permalink to &quot;1、踏频&quot;">​</a></h3><p>保持稳定的踏频 RPM（Revolutions Per Minute），表示每分钟踩了几圈。一般是 80-90，根据自身条件来调整，关键是稳定。</p><p>合理的踏频能够有效使用身体机能，防止肌肉和膝关节损伤。</p><p>让双脚保持适当的踩踏力度，如果遇到道路上下坡，通过变速器来调整速度，目的是通过改变速度来保持踩踏的力度稳定。不空踩也不费力的踩。</p><h3 id="_2、牙盘和飞轮的搭配" tabindex="-1">2、牙盘和飞轮的搭配 <a class="header-anchor" href="#_2、牙盘和飞轮的搭配" aria-label="Permalink to &quot;2、牙盘和飞轮的搭配&quot;">​</a></h3><p><img src="'+s+'" alt=""></p><h3 id="_3、变速的时机" tabindex="-1">3、变速的时机 <a class="header-anchor" href="#_3、变速的时机" aria-label="Permalink to &quot;3、变速的时机&quot;">​</a></h3><p>预测前方道路变化，要保持速度，提前变速，轻踩踏板，先飞轮后牙盘。 因为飞轮的盘数更多，可以进行更精确的调整，等飞轮调整到需要跨牙盘刻度的时候，再调整牙盘。</p><h2 id="轮胎" tabindex="-1">轮胎 <a class="header-anchor" href="#轮胎" aria-label="Permalink to &quot;轮胎&quot;">​</a></h2><h3 id="合理的胎压" tabindex="-1">合理的胎压 <a class="header-anchor" href="#合理的胎压" aria-label="Permalink to &quot;合理的胎压&quot;">​</a></h3><p>一般自行车轮胎上都会刻印出该轮胎需要的胎压标准，比如 ATX660 的原装轮胎显示的是</p><p><code>REO PRESSURE 35 PSI / 240 kPa / 2.4 BAR</code></p><p>和</p><p><code>MAX PRESSURE 65 PSI / 450 kPa / 4.5 BAR</code></p><p>我喜欢采用 PSI 的单位，所以取中间值 50 PSI 来当作标准胎压。如果是冬天会打到 55 PSI 来适应低温的影响。</p><h3 id="换内胎" tabindex="-1">换内胎 <a class="header-anchor" href="#换内胎" aria-label="Permalink to &quot;换内胎&quot;">​</a></h3><p>轮胎上显示 <code>26 x 1.95</code>，所以内胎选择尺寸范围内的就好。如我买的是 <code>26 x 1.9/2.125</code>。</p><p><img src="'+l+'" alt=""></p><h3 id="补内胎" tabindex="-1">补内胎 <a class="header-anchor" href="#补内胎" aria-label="Permalink to &quot;补内胎&quot;">​</a></h3><p><img src="'+c+'" alt=""></p><p>不管是拆胎还是装胎，都要从气嘴开始，先将气嘴拆装，再拆装整个内胎。</p><p>拆胎，将气体全部放掉。</p><p>装胎，稍微打一些气，更好塞入外胎。</p><p><img src="'+n+'" alt=""></p><h2 id="配件" tabindex="-1">配件 <a class="header-anchor" href="#配件" aria-label="Permalink to &quot;配件&quot;">​</a></h2><p>前后反光灯都拆掉了，没有夜间骑车的需求，城市中路灯覆盖充足，不喜欢功能性不强的配件挂在车上。</p>',30)])])}const x=e(p,[["render",d]]);export{q as __pageData,x as default};
